import { chromium } from '@playwright/test';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { cpus } from 'node:os';
import assert from 'node:assert/strict';
import ts from 'typescript';
import Original from '@xterm/xterm';
import { Terminal } from '../packages/wraith/dist/xterm.js';
import { inputFixtures } from '../scripts/performance-experiments/fixtures.mjs';
const kinds = ['baseline', 'prefix', 'sgr', 'combined'];
const parserSource = await readFile('packages/wraith/src/xterm-parser.js', 'utf8');
let prefix = parserSource.slice(parserSource.indexOf('function fastParse'));
const oldStart = prefix.indexOf('                    do {', prefix.indexOf('case ParserAction.PARAM:'));
const oldEnd = prefix.indexOf('                    store[index] = value;', prefix.indexOf('} while (++i < length',oldStart));
prefix = prefix.slice(0,oldStart) + `                    for (;;) {
                      while (code >= 48 && code <= 57 && i < length) {
                        value = Math.min(2147483647, value * 10 + code - 48);
                        code = data[++i];
                      }
                      store[index] = value;
                      if (code !== 59 || i >= length) break;
                      p.addParam(0);
                      if (p._rejectDigits) break;
                      index++; value = 0; code = data[++i];
                    }
` + prefix.slice(oldEnd);
const constants = parserSource.slice(parserSource.indexOf('var TableAccess'), parserSource.indexOf('export function'));
const prefixCode = constants + '\nreturn ' + prefix;
const decoderSource = await readFile('node_modules/@wraith-terminal/xterm-base/src/common/input/TextDecoder.ts', 'utf8');
let decoder = decoderSource.slice(decoderSource.indexOf('  public decode(input: Uint8Array'), decoderSource.lastIndexOf('\n}')).replace('  public decode(input:', 'function decode(this: any, input:');
decoder = decoder.replace(/&& !\(\(byte1 = input\[i\]\) & 0x80\)\s*&& !\(\(byte2 = input\[i \+ 1\]\) & 0x80\)\s*&& !\(\(byte3 = input\[i \+ 2\]\) & 0x80\)\s*&& !\(\(byte4 = input\[i \+ 3\]\) & 0x80\)/, '&& !(((byte1 = input[i]) | (byte2 = input[i + 1]) | (byte3 = input[i + 2]) | (byte4 = input[i + 3])) & 0x80)');
const decoderCode = 'return ' + ts.transpileModule(decoder, {compilerOptions:{target: ts.ScriptTarget.ES2022}}).outputText;
const inputSource = await readFile('packages/wraith/dist/xterm-input.js', 'utf8');
const sgrStart = inputSource.indexOf('input.charAttributes = function');
const sgr = 'return ' + inputSource.slice(sgrStart + 'input.charAttributes = '.length, inputSource.lastIndexOf('\n}')).replace('const values = params.params;', 'if (params._subParamsLength !== 0) return attributes.call(this, params);\n        const values = params.params;').replace('if (params.hasSubParams(i))\n                return attributes.call(this, params);', '').replace(/for \(let j = i \+ 1; j <= i \+ advance; j\+\+\)\s*if \(params.hasSubParams\(j\)\)\s*return attributes.call\(this, params\);/, '');
const source = {prefixCode, decoderCode, sgr};
for (const kind of ['prefix']) {
 const validation = await inputFixtures(Terminal, Original.Terminal, t => {const input=t._core._inputHandler; if(kind==='prefix')input._parser.parse = new Function(prefixCode)(); if(kind==='decoder')input._utf8Decoder.decode=new Function(decoderCode)(); if(kind==='sgr')input.charAttributes=new Function('attributes', sgr)(input.charAttributes);});
 console.log(kind, validation);
}
const root = process.cwd(),
  output = process.env.WRAITH_REPORT_DIR ?? '.cache/gold-input-paired';
const pairs = Number(process.env.WRAITH_PAIRS ?? 40),
  frames = 32;
assert(Number.isInteger(pairs) && pairs >= 20 && pairs <= 200);
const sha = (b) => createHash('sha256').update(b).digest('hex');
await mkdir(output, { recursive: true });
async function interleaved(a, options) {
  const input = a.terminal._core._inputHandler,
    parser = input._parser;
  const baseline = {parser:parser.parse, decoder:input._utf8Decoder.decode, sgr:input.charAttributes};
  const variants = {parser:new Function(options.source.prefixCode)(), decoder:new Function(options.source.decoderCode)(), sgr:new Function('attributes',options.source.sgr)(input.charAttributes)};
  const kinds = ['baseline','prefix','sgr','combined'];
  const select = kind => {parser.parse = kind==='prefix'||kind==='combined'?variants.parser:baseline.parser;
    input._utf8Decoder.decode = kind==='decoder'||kind==='combined'?variants.decoder:baseline.decoder;
    input.charAttributes=kind==='sgr'||kind==='combined'?variants.sgr:baseline.sgr;};
  for(const kind of kinds){select(kind); for(let i=0;i<128;i++){a.parse(a.inputs[i%8].bytes); a.draw();if((i+1)%32===0)await a.finish();} await a.finish();}
  const results = [];
  for (let pair = 0; pair < options.pairs; pair++) {
    let order = pair % 2 ? [...kinds].reverse() : [...kinds];
    order = order.map((_, i) => order[(i + (pair % kinds.length)) % kinds.length]);
    for (const kind of order) {
      select(kind);
      const before = a.submitted(),
        started = performance.now();
      for (let i = 0; i < options.frames; i++) {
        a.parse(a.inputs[i % 8].bytes);
        a.draw();
      }
      await a.finish();
      const elapsedMs = performance.now() - started,
        submitted = a.submitted() - before;
      if (submitted !== options.frames) throw new Error('Paired submission count mismatch');
      results.push({
        pair,
        kind,
        elapsedMs,
        frames: options.frames,
        submittedFrames: submitted,
        updatesPerSecond: (options.frames * 1000) / elapsedMs,
      });
    }
  }
  select('baseline');
  a.assert();
  return results;
}
const metadata = {
  date: new Date().toISOString(),
  head: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(),
  hardware: { cpu: cpus()[0]?.model, logicalCpus: cpus().length },
  pairs,
  framesPerBlock: frames,
  method:
    'Same terminal and GPU device. Warm each action 256 updates. Alternate/rotate three actions every 32 real input updates, fence every block. All submissions counted. No parser/pixel validation or profiling runs concurrently. Fixed current workload bytes; existing SGR acceleration retained in all modes. GPU-completed throughput, not presentation FPS.',
  sources: Object.fromEntries(
    await Promise.all(
      [
        'scripts/paired-production-input.mjs',
        'scripts/generate-xterm-parser.mjs',
        'packages/wraith/src/xterm-parser.js',
        'packages/wraith/src/xterm-print.ts',
        'demo/compare.js',
        'demo/showcase.js',
        'demo/pipes-scene.js',
        'packages/wraith/src/xterm.ts',
        'packages/wraith/src/xterm-input.ts',
        'packages/wraith/src/xterm-renderer.ts',
        'packages/wraith/wasm/wraith_engine_bg.wasm',
      ].map(async (f) => [f, sha(await readFile(f))]),
    ),
  ),
  source,
  results: [],
  errors: [],
};
const save = () => writeFile(output + '/runs.json', JSON.stringify(metadata, null, 2) + '\n');
await save();
const browser = await chromium.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
});
try {
  const conditions = ['complex', 'pipes'].map((workload) => ({
    workload,
    dpr: 1,
  }));

  for (const condition of conditions) {
    const context = await browser.newContext({
      viewport: { width: 2600, height: 2100 },
      deviceScaleFactor: condition.dpr,
    });
    const page = await context.newPage(),
      errors = [];
    page.on('pageerror', (e) => errors.push(e.message));
    await page.route('**/compare.js*', async (route) => {
      const response = await route.fetch();
      let body = await response.text();
      assert(body.includes('window.comparison = {'));
      body =
        `const interleaved=${interleaved.toString()};\n` +
        body.replace(
          'window.comparison = {',
          'window.comparison = { paired:options=>interleaved(active,options),',
        );
      await route.fulfill({ response, body });
    });
    await page.goto(
      `http://127.0.0.1:5201/compare.html?type=wraith&workload=${condition.workload}`,
    );
    await page.waitForFunction(() => window.comparison?.ready, undefined, { timeout: 60000 });
    assert(await page.evaluate(() => window.comparison.ready));
    metadata.userAgent ??= await page.evaluate(() => navigator.userAgent);
    metadata.adapter ??= await page.evaluate(() => window.comparison.adapterInfo());
    const results = await page.evaluate((options) => window.comparison.paired(options), {
      pairs,
      frames, source,
    });
    assert.deepEqual(errors, []);
    metadata.results.push({ ...condition, results });
    await save();
    console.log(
      `${condition.workload} DPR${condition.dpr}: ${pairs} rotated baseline/params/combined blocks completed`,
    );
    await page.evaluate(() => window.comparison.dispose());
    await context.close();
  }
} finally {
  await browser.close();
}
const median = (xs) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)];
const summary = metadata.results.map((row) => {
  const modes = kinds.map((kind) => {
    const runs = row.results.filter((r) => r.kind === kind),
      rates = runs.map((r) => r.updatesPerSecond);
    const ratios =
      kind === 'baseline'
        ? [1]
        : runs.map(
            (r) =>
              r.updatesPerSecond /
              row.results.find((b) => b.pair === r.pair && b.kind === 'baseline').updatesPerSecond,
          );
    const sorted = [...ratios].sort((a, b) => a - b);
    return {
      kind,
      completedUpdatesPerSecond: median(rates),
      pairedMedianRatio: median(ratios),
      pairedRatioP10: sorted[Math.floor(sorted.length * 0.1)],
      pairedRatioP90: sorted[Math.floor(sorted.length * 0.9)],
    };
  });
  return { workload: row.workload, dpr: row.dpr, modes };
});
for (const [file, hash] of Object.entries(metadata.sources))
  assert.equal(sha(await readFile(file)), hash, 'Source changed during paired batch');
await writeFile(
  output + '/summary.json',
  JSON.stringify({ date: metadata.date, pairs, framesPerBlock: frames, summary }, null, 2) + '\n',
);
console.log(JSON.stringify(summary, null, 2));
